<template>
  <p v-if="audit?.updated_at" class="text-xs text-muted-foreground mt-2">
    Last updated {{ formatDateToFormat(audit.updated_at, 'MM/dd/yyyy, hh:mm aaa') }}
    <span v-if="audit.updated_by">
      by
      <span v-if="isCurrentUser">you</span>
      <InlineEntityUser v-else :user-id="audit.updated_by" />
    </span>
  </p>
</template>

<script setup lang="ts">
import type { AuditInfo } from '~/client';

const props = defineProps<{
  audit: AuditInfo | null;
}>();

const { userId } = useUserRole();
const isCurrentUser = computed(() => !!props.audit?.updated_by && props.audit.updated_by === userId.value);
</script>
